package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;

/** Actual day worker and known configuration failure, then owner recovery using original proofs. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class OwnerJobRecoverMySqlTest {
    SourceDayWorkerIntegrationMySqlTest f;WorkerAuthorizationService.Identity identity;OwnerJobRecoverService service;long revision;
    final IdentityService.Actor owner=new IdentityService.Actor("fictional-owner","owner");
    @BeforeEach void setup()throws Exception{
        f=new SourceDayWorkerIntegrationMySqlTest();f.setup();f.db.jdbc.execute("ALTER TABLE jobs ADD error_code VARCHAR(64), ADD retry_of_job_id VARCHAR(64)");
        var claim=f.worker.claim(f.action());identity=claim.permit().identity();assertEquals(WorkerAuthorizationService.State.SENT,f.worker.dispatch(claim.permit(),request->"fictional-provider-configuration-failure").state());
        assertEquals("blocked_configuration",new AttemptFailureService(f.db.writes,new JdbcAttemptFailure(f.db.source),f.f.f.clock,"fictional-actual-day-worker").fail(identity,AttemptFailureService.Failure.CONFIGURATION,null,new SharedWriteExecutor.ActionContext("fictional-known-configuration-failure",f.root,null)).state());
        revision=new JdbcJobRecords(f.db.source).byId(f.root).revision();service=new OwnerJobRecoverService(f.db.writes,new JdbcOwnerJobRecovery(f.db.source),f.readiness,f.f.day.manager,f.f.f.clock);
    }
    JdbcOwnerJobRecovery.Recovered recover(String key){return service.recover(owner,f.root,revision,"Fictional original input recovery",key);}
    @Test void realRecoveryRequeuesSameRootAndPreparesExactOriginalRequestWithoutCallingOrRefunding(){var slot=f.state.slot();var result=recover("fictional-recovery!");assertEquals(f.root,result.rootId());assertEquals(revision+1,result.revision());assertEquals(1,result.calls());assertEquals(2,f.db.count("record_kind='ai_attempt' AND root_job_id='"+f.root+"'"));assertEquals(slot,f.state.slot());assertEquals("queued",new JdbcJobRecords(f.db.source).byId(f.root).state());var attempt=new JdbcJobRecords(f.db.source).byId(result.attemptId());assertEquals(2,attempt.attemptNo());assertEquals("prepared",attempt.state());assertEquals(identity.frozenRequestJson(),attempt.requestJson());assertEquals(identity.inputHash(),f.db.jdbc.queryForObject("SELECT LOWER(HEX(input_hash)) FROM jobs WHERE id=?",String.class,result.attemptId()));assertEquals(1,new JdbcJobRecords(f.db.source).byId(f.root).callCount());assertEquals(1,f.db.count("target_type='worker_send'"));}
    @Test void originalReceiptReplaysDespiteLaterNativeOrDayChangesAndRebindingRefuses(){var result=recover("fictional-replay");f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",f.root);f.loseRegistration();assertEquals(result,recover("fictional-replay"));assertEquals("identity_conflict",assertThrows(JdbcOwnerJobRecovery.Rejected.class,()->service.recover(owner,f.root,revision,"Fictional changed reason","fictional-replay")).getMessage());assertEquals(1,f.db.count("target_type='job_recover'"));}
    @Test void actualOriginalPreparedNextAttemptIsReusedAndNewerSlotIsUntouched(){String next=JdbcFrozenInputs.stableId("attempt",f.root+":2");f.db.writes.execute(new SharedWriteExecutor.ActionContext("fictional-prepare-next",f.root,null),key->null,c->{new JdbcJobRecords(f.db.source).prepareAttempt(new JdbcJobRecords.Attempt(next,f.root,2,identity.frozenRequestJson(),f.root,identity.inputHash()),f.f.f.clock.instant());return true;});f.db.jdbc.update("UPDATE worker_lock SET slot_state='occupied',job_id='fictional-new-attempt',holder='fictional-new-worker',slot_revision=slot_revision+1,fencing_token=fencing_token+1");var slot=f.state.slot();assertEquals(next,recover("fictional-reuse").attemptId());assertEquals(2,f.db.count("record_kind='ai_attempt' AND root_job_id='"+f.root+"'"));assertEquals(slot,f.state.slot());}
    @Test void unknownExhaustedWrongRevisionAndRoleRefuseWithoutNewAttempt(){assertEquals("revision_conflict",assertThrows(JdbcOwnerJobRecovery.Rejected.class,()->service.recover(owner,f.root,revision+1,"Fictional stale","fictional-stale")).getMessage());f.db.jdbc.update("UPDATE jobs SET call_count=3 WHERE id=?",f.root);assertEquals("retry_exhausted",assertThrows(JdbcOwnerJobRecovery.Rejected.class,()->recover("fictional-exhausted")).getMessage());f.db.jdbc.update("UPDATE jobs SET call_count=1,state='unknown_external' WHERE id=?",f.root);assertEquals("external_result_unresolved",assertThrows(JdbcOwnerJobRecovery.Rejected.class,()->recover("fictional-unknown")).getMessage());assertThrows(IdentityService.Rejected.class,()->service.recover(new IdentityService.Actor("fictional-member","member"),f.root,revision,"Fictional role","fictional-role"));assertEquals(1,f.db.count("record_kind='ai_attempt' AND root_job_id='"+f.root+"'"));assertEquals(0,f.db.count("target_type='job_recover'"));}
    @Test void lostActualDayProofOrReceiptConstraintRollsBackAllRootAndAttemptWrites(){f.db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_recover_receipt CHECK(target_type IS NULL OR target_type<>'job_recover')");assertThrows(RuntimeException.class,()->recover("fictional-receipt-fault"));assertEquals(revision,new JdbcJobRecords(f.db.source).byId(f.root).revision());assertEquals("blocked_configuration",new JdbcJobRecords(f.db.source).byId(f.root).state());assertEquals(1,f.db.count("record_kind='ai_attempt' AND root_job_id='"+f.root+"'"));f.db.jdbc.execute("ALTER TABLE jobs DROP CHECK fictional_recover_receipt");f.loseRegistration();assertThrows(RuntimeException.class,()->recover("fictional-lost-day"));assertEquals(revision,new JdbcJobRecords(f.db.source).byId(f.root).revision());assertEquals(0,f.db.count("target_type='job_recover'"));}
    @Test void originalReceiptHashDamageIsRefused(){var result=recover("fictional-damage");f.db.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='job_recover'",new byte[32]);assertThrows(JdbcOwnerJobRecovery.Rejected.class,()->recover("fictional-damage"));assertEquals(result.revision(),new JdbcJobRecords(f.db.source).byId(f.root).revision());}
    @Test void damagedOriginalRequestCannotBeCopiedIntoAUsableNextAttempt(){f.db.jdbc.update("UPDATE jobs SET request_json=? WHERE id=?","{\"fictional\":\"damaged\"}",identity.attemptId());assertThrows(RuntimeException.class,()->recover("fictional-bad-request"));assertEquals(revision,new JdbcJobRecords(f.db.source).byId(f.root).revision());assertEquals(1,f.db.count("record_kind='ai_attempt' AND root_job_id='"+f.root+"'"));assertEquals(0,f.db.count("target_type='job_recover'"));}
    @Test void originalDayRegistrationLostInsideWriterMakesQueueAndNextAttemptRollBack(){int receipts=f.db.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts WHERE actor_id='source-day-register'",Integer.class);assertTrue(receipts>0);f.db.jdbc.execute("CREATE TRIGGER fictional_recovery_day_loss BEFORE UPDATE ON jobs FOR EACH ROW BEGIN IF NEW.state='queued' AND OLD.state='blocked_configuration' THEN DELETE FROM request_receipts WHERE actor_id='source-day-register'; END IF; END");assertThrows(RuntimeException.class,()->recover("fictional-writer-day-loss"));assertEquals(revision,new JdbcJobRecords(f.db.source).byId(f.root).revision());assertEquals(1,f.db.count("record_kind='ai_attempt' AND root_job_id='"+f.root+"'"));assertEquals(receipts,f.db.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts WHERE actor_id='source-day-register'",Integer.class));assertEquals(0,f.db.count("target_type='job_recover'"));}
    @Test void missingRootRefusesWithNotFoundBeforeInputCapture(){assertEquals("not_found",assertThrows(JdbcOwnerJobRecovery.Rejected.class,()->service.recover(owner,"fictional-absent",0,"Fictional missing root","fictional-missing-root")).getMessage());assertEquals(0,f.db.count("target_type='job_recover'"));}
}
